p='src/wrenches.ts'; s=open(p).read()
s=s.replace('type WrenchReport = { bike_id?: string; fault?: string };','type WrenchReport = { bike_id?: string; fault?: string; request_id?: string };')
s=s.replace("""export function recordWrench(database: Database, report: WrenchReport) {
""","""export function recordWrench(database: Database, report: WrenchReport) {
  // The rider app retries a failed POST /wrench with the same request_id. A retry is the
  // same report: answer with the job it already opened, and open no new job (postmortem A-1).
  const requestId = typeof report.request_id === "string" && report.request_id ? report.request_id : null;
  if (requestId) {
    const earlier = database
      .query("SELECT bike_id, job_id FROM wrenches WHERE request_id = ?")
      .get(requestId) as { bike_id: string; job_id: string } | null;
    if (earlier) return { status: 200, body: { job_id: earlier.job_id, bike_id: earlier.bike_id } };
  }
""")
