      .run(bike_id, station_id, fault, reportedAt);""","""      .query(
        "INSERT INTO wrenches (bike_id, station_id, fault, reported_at, request_id, job_id) VALUES (?, ?, ?, ?, ?, ?)",
      )
      .run(bike_id, station_id, fault, reportedAt, requestId, jobId);""")
s=s.replace("logEvent(\"wrench\", { bike_id, station_id, fault, job_id: jobId });","logEvent(\"wrench\", { bike_id, station_id, fault, job_id: jobId, request_id: requestId });")
open(p,'w').write(s)
EOF
